def c(s): return '"'+s.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n')+'"'
# comprobar: ninguna traducción coincide con otra clave distinta (T se puede aplicar dos veces)
for k,v in TR.items():
    if v in TR and TR[v]!=v and v!=k: print("conflicto",k,v,file=sys.stderr)
items=sorted(TR.items(), key=lambda kv: kv[0].encode())
out=['// Traducciones de la interfaz (español -> inglés), ordenadas por bytes para bsearch. Generado con scripts/i18n_gen.py; editar allí.',
     'static const char *const I18N[][2] = {']
out+=['\t{%s, %s},'%(c(k),c(v)) for k,v in items]
out.append('};')
open(__import__("os").path.join(__import__("os").path.dirname(__file__), "..", "ui", "i18n.h"),'w').write('\n'.join(out)+'\n')
print(len(items),"entradas")
